def transform(grid):
    out=[r[:] for r in grid]
    h,w=len(grid),len(grid[0])
    counts={}
    for row in grid:
        for v in row: counts[v]=counts.get(v,0)+1
    marker=min(counts, key=counts.get)
    for i in range(h):
        pts=[j for j,v in enumerate(grid[i]) if v==marker]
        for a,b in zip(pts,pts[1:]):
            for j in range(a+1,b): out[i][j]=3
    for j in range(w):
        pts=[i for i in range(h) if grid[i][j]==marker]
        for a,b in zip(pts,pts[1:]):
            for i in range(a+1,b): out[i][j]=3
    return out
